   137
   138    closure = (hb_face_for_data_closure_t *) calloc (1, sizeof (hb_face_for_data_closure_t));
   139    if (unlikely (!closure))
   140      return nullptr;
   141
   142    closure->blob = blob;
   143    closure->index = index;
   144
   145    return closure;
